    @Test
    public void RepeatPublicationsAreTheirOwnCards() {
        assertEquals(67, REPEATS.size());
        REPEATS.forEach((id, v) -> {
            SwccgCardBlueprint card = library.getSwccgoCardBlueprint(id);
            assertNotNull(id, card);
            assertEquals(id, id, library.getBaseBlueprintId(id));
            LegacyVersion version = card.getLegacyVersion();
            assertNotNull(id, version);
            assertEquals(id, v[0], version.currentPrintingId());
            assertEquals(id, v[1], version.label());
            assertEquals(id, v[2], card.getGameText());
            assertEquals(id, date(v[3]), version.printedOn());
            assertEquals(id, date(v[4]), version.supersededOn());
            assertEquals(id, library.getSwccgoCardBlueprint(v[0]).getTitle(), card.getTitle());
        });
    }

    private static SwccgCardBlueprintLibrary library;

    @BeforeClass
    public static void setUpClass() {
        library = new SwccgCardBlueprintLibrary();
    }

    private static LocalDate date(String ymd) {
        String[] p = ymd.split(", ");
        return LocalDate.of(Integer.parseInt(p[0]), Integer.parseInt(p[1]), Integer.parseInt(p[2]));
    }

    @Test
    public void CurrentCardsCarryTheMasterListText() {
        assertEquals(67, CURRENT_TEXT.size());
        CURRENT_TEXT.forEach((id, text) -> {
            SwccgCardBlueprint card = library.getSwccgoCardBlueprint(id);
            assertNotNull(id, card);
            assertNull(id, card.getLegacyVersion());
            assertEquals(id, text, card.getGameText());
        });
        assertEquals(CURRENT_TEXT.get("1281_30"), library.getSwccgoCardBlueprint("1281_30ai").getGameText());
    }

    @Test
    public void CardListTextsAreTheirOwnCards() {
        assertEquals(68, VERSIONS.size());
        VERSIONS.forEach((id, v) -> {
            SwccgCardBlueprint card = library.getSwccgoCardBlueprint(id);
            assertNotNull(id, card);
            assertEquals(id, id, library.getBaseBlueprintId(id));
            LegacyVersion version = card.getLegacyVersion();
            assertNotNull(id, version);
            assertEquals(id, v[0], version.currentPrintingId());
            assertEquals(id, v[1], version.label());
            assertEquals(id, v[2], card.getGameText());
            assertEquals(id, date(v[3]), version.printedOn());
            // Virtual Blocks 5-7: superseded by the PC card image (server upload 2013-02-25); Virtual Block 8: by the Master List
            assertEquals(id, id.startsWith("228") ? LocalDate.of(2013, 4, 27) : LocalDate.of(2013, 2, 25), version.supersededOn());
            SwccgCardBlueprint current = library.getSwccgoCardBlueprint(v[0]);
            assertEquals(id, current.getTitle(), card.getTitle());
            assertEquals(id, current.getLore(), card.getLore());
        });
    }

    @Test
    public void ObiWanInRadiantViiCardListTitleMovesToItsVersion() {
        assertEquals("Obi-Wan In Radiant VII", library.getSwccgoCardBlueprint("1250_83").getTitle());
        assertNull(library.getSwccgoCardBlueprint("1250_83").getPrintedTitle());
    }

    @Test
    public void AmbushAndBaragwinCardListVersionsPlayTheirOwnText() {
        assertTrue(library.getSwccgoCardBlueprint("2250_1065") instanceof com.gempukku.swccgo.cards.set2250.light.Card2250_1065);
        assertTrue(library.getSwccgoCardBlueprint("2261_1062") instanceof com.gempukku.swccgo.cards.set2261.light.Card2261_1062);
        assertEquals("Obi-Wan in Radiant VII", library.getSwccgoCardBlueprint("2250_1083").getPrintedTitle());
    }
